            case_insensitive = true;
        }
    }
    if case_insensitive {
        p = format!("(?i){}", p);
    }
    if config.word_regexp {
        p = format!(r"\\b(?:{})\\b", p);
    }
    match regex::Regex::new(&p) {
        Ok(r) => Ok(r),
        Err(e) => Err(format!("Error {{ kind: Regex({:?}) }}", e.to_string())),
    }
}

fn contains_explicit_newline(pat: &str) -> bool {
    // Use regex-syntax HIR to detect literal \\n (not class)
    let hir = match regex_syntax::Parser::new().parse(pat) {
        Ok(h) => h,
        Err(_) => return false,
    };
    hir_contains_newline_literal(&hir)
