fn hir_contains_newline_literal(hir: &regex_syntax::hir::Hir) -> bool {
    use regex_syntax::hir::HirKind;
    match hir.kind() {
        HirKind::Literal(lit) => lit.0.contains(&b'\\n'),
        HirKind::Class(_) => false,
        HirKind::Look(_) => false,
        HirKind::Empty => false,
        HirKind::Repetition(rep) => hir_contains_newline_literal(&rep.sub),
        HirKind::Capture(cap) => hir_contains_newline_literal(&cap.sub),
        HirKind::Concat(hirs) => hirs.iter().any(hir_contains_newline_literal),
        HirKind::Alternation(alts) => alts.iter().any(hir_contains_newline_literal),
    }
}

