#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Editor {
    Vim, Neovim, Nvim, Nano, Code, Vscode, CodeInsiders, Emacs, Emacsclient, Hx, Helix, Subl, SublimeText, Micro, Intellij, Goland, Pycharm, Less, Fresh,
}

fn editor_possible_values() -> Vec<&'static str> {
    vec!["vim", "neovim", "nvim", "nano", "code", "vscode", "code-insiders", "emacs", "emacsclient", "hx", "helix", "subl", "sublime-text", "micro", "intellij", "goland", "pycharm", "less", "fresh"]
}

impl FromStr for Editor {
    type Err = anyhow::Error;
    fn from_str(s: &str) -> Result<Self> {
        match s {
            "vim" => Ok(Editor::Vim),
            "neovim" => Ok(Editor::Neovim),
            "nvim" => Ok(Editor::Nvim),
            "nano" => Ok(Editor::Nano),
            "code" => Ok(Editor::Code),
            "vscode" => Ok(Editor::Vscode),
            "code-insiders" => Ok(Editor::CodeInsiders),
            "emacs" => Ok(Editor::Emacs),
            "emacsclient" => Ok(Editor::Emacsclient),
            "hx" => Ok(Editor::Hx),
            "helix" => Ok(Editor::Helix),
            "subl" => Ok(Editor::Subl),
            "sublime-text" => Ok(Editor::SublimeText),
            "micro" => Ok(Editor::Micro),
            "intellij" => Ok(Editor::Intellij),
            "goland" => Ok(Editor::Goland),
            "pycharm" => Ok(Editor::Pycharm),
            "less" => Ok(Editor::Less),
            "fresh" => Ok(Editor::Fresh),
            _ => Err(anyhow::anyhow!("invalid variant: {}", s)),
        }
    }
}

fn editor_program_and_args(editor: Editor, file: &str, line: u64) -> (String, Vec<String>) {
    match editor {
        Editor::Vim => ("vim".to_string(), vec![format!("+{}", line), file.to_string()]),
        Editor::Neovim | Editor::Nvim => ("nvim".to_string(), vec![format!("+{}", line), file.to_string()]),
        Editor::Nano => ("nano".to_string(), vec![format!("+{}", line), file.to_string()]),
        Editor::Code | Editor::Vscode => ("code".to_string(), vec![format!("-g"), format!("{}:{}", file, line)]),
        Editor::CodeInsiders => ("code-insiders".to_string(), vec![format!("-g"), format!("{}:{}", file, line)]),
        Editor::Emacs => ("emacs".to_string(), vec!["-nw".to_string(), format!("+{}", line), file.to_string()]),
        Editor::Emacsclient => ("emacsclient".to_string(), vec!["-nw".to_string(), format!("+{}", line), file.to_string()]),
        Editor::Hx => ("hx".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Helix => ("helix".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Subl | Editor::SublimeText => ("subl".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Micro => ("micro".to_string(), vec![format!("+{}", line), file.to_string()]),
        Editor::Intellij => ("idea".to_string(), vec!["--line".to_string(), format!("{}", line), file.to_string()]),
        Editor::Goland => ("goland".to_string(), vec!["--line".to_string(), format!("{}", line), file.to_string()]),
        Editor::Pycharm => ("pycharm".to_string(), vec!["--line".to_string(), format!("{}", line), file.to_string()]),
        Editor::Less => ("less".to_string(), vec![format!("+{}", line), file.to_string()]),
        Editor::Fresh => ("fresh".to_string(), vec![format!("{}:{}", file, line)]),
    }
}

#[derive(Debug, Clone)]
struct CustomCommand {
    program: String,
    args_template: Vec<String>,
}

fn parse_custom_command(s: &str) -> Result<CustomCommand> {
    // Split by ' ' (space only, not other whitespace)
    // Keep empty tokens? For validation, need to handle multiple spaces.
    // Original splits by ' ' and keeps empties? For "vim  {file}   {line}  " (multiple spaces), it was valid.
    // If we split by ' ' and filter empty, we get ["vim", "{file}", "{line}"] -> valid.
    // If we keep empties, program="vim", args include empties + tokens -> still valid (counts same).
    // For " " (single space), split gives ["", ""] -> program="", args=[""] -> has program+args, missing tokens -> file error. Good.
    // For "" (empty), split gives [""] -> single token, no args -> program error. Good.
    // For "\t" (tab, no spaces), split gives ["\t"] -> single token -> program error. Good.
    // So split by ' ' keeping empties, then check.
    let parts: Vec<&str> = s.split(' ').collect();
    // Check program + args: need at least 2 parts (program + at least one arg)? Actually need program + args (at least 1 arg)?
    // For "", parts=[""] (len 1) -> program error.
    // For "vim" (single word, no spaces), parts=["vim"] (len 1) -> program error.
    // For " " (single space), parts=["",""] (len 2) -> has program+args, check tokens.
    if parts.len() < 2 {
        return Err(anyhow::anyhow!("Expected program and its arguments").context(format!("Incorrect editor command: '{}'", s)));
    }
    let program = parts[0].to_string();
    let args: Vec<String> = parts[1..].iter().map(|s| s.to_string()).collect();
    // Count occurrences of tokens in args (excluding program), counting substrings?
    // Tokens can be substrings (e.g., "+{line_number}"), so count occurrences via string contains count?
    // Need to count number of occurrences of "{file_name}" and "{line_number}" across all args (as substrings).
    // For "vim {file_name} {file_name} {line_number}", file count=2 -> error.
    // For "vim {file_name}xx {line_number}", file count=1 (substring) -> valid.
    // For "vim{file_name} {line_number}", program contains file, args contain line once, file zero -> error about file.
    // Implementation: join args with ' ' (or count per arg via matches)?
    // Use .matches() to count occurrences (non-overlapping).
    let args_joined = args.join(" ");
    // Actually need to count across args, but joining with space is fine (since tokens don't contain spaces).
    let file_count = args_joined.matches("{file_name}").count();
    let line_count = args_joined.matches("{line_number}").count();
    if file_count != 1 {
        return Err(anyhow::anyhow!("Expected one occurrence of '{{file_name}}'.").context(format!("Incorrect editor command: '{}'", s)));
    }
    if line_count != 1 {
        return Err(anyhow::anyhow!("Expected one occurrence of '{{line_number}}'.").context(format!("Incorrect editor command: '{}'", s)));
    }
    Ok(CustomCommand { program, args_template: args })
}

