        Editor::Emacs => ("emacs".to_string(), vec!["-nw".to_string(), format!("+{}", line), file.to_string()]),
        Editor::Emacsclient => ("emacsclient".to_string(), vec!["-nw".to_string(), format!("+{}", line), file.to_string()]),
        Editor::Hx => ("hx".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Helix => ("helix".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Subl | Editor::SublimeText => ("subl".to_string(), vec![format!("{}:{}", file, line)]),
        Editor::Micro => ("micro".to_string(), vec![format!("+{}", line), file.to_string()]),
