    let editor_cli: Option<&String> = matches.get_one("editor");
    let custom_cli: Option<&String> = matches.get_one("custom-command");

    // Validate custom/editor (custom already conflicts with editor via clap, including env)
    // If custom present (CLI or env via clap), parse it
    let custom_command: Option<CustomCommand> = if let Some(s) = custom_cli {
        Some(parse_custom_command(s)?)
    } else {
