                    // Present (even if empty) -> try parse, on error return with context
                    match Editor::from_str(&val) {
                        Ok(ed) => { found = Some(ed); break; }
                        Err(inner) => {
                            // inner is anyhow with "invalid variant: ..."
                            // Need to return Error: "\"val\" read from $VAR, possible variants: [...]" + Caused by inner
                            let outer = format!("\"{}\" read from ${}, possible variants: [{}]", val, var, possible);
                            return Err(inner.context(outer));
                        }
                    }
                } else {
