            let _ = ig::searcher::build_matcher(&cfg);
        });
        // Give background thread a moment to panic and print? Original prints panic to stderr.
        // For TTY case, exit 0 (no TUI). For non-TTY, return EAGAIN error (exit 1) with panic already printed.
        // Check TTY
        let is_tty = std::io::stdout().is_terminal() && std::io::stdin().is_terminal();
        if is_tty {
            // Exit 0, no TUI. Need to ensure panic prints? Sleep briefly to allow panic output before exit?
            // Original shows panic after EXIT:0 (when we sleep 1s before cat). If we exit immediately, panic may still print (since thread already spawned).
            // Sleep 100ms to allow panic to print before exit? Actually exit 0 will terminate process, background thread may be killed before printing.
            // To ensure panic prints, we should sleep a bit. Original must do something similar (or join?).
            // Let's sleep 200ms.
            std::thread::sleep(std::time::Duration::from_millis(200));
            std::process::exit(0);
        } else {
            // No TTY: return EAGAIN error. Sleep briefly to allow panic to print first (as observed panic first, then EAGAIN)?
            std::thread::sleep(std::time::Duration::from_millis(200));
            return Err(anyhow::anyhow!(std::io::Error::from_raw_os_error(11)));
        }
    }

    // Check TTY for valid patterns (no panic). If no TTY, return EAGAIN immediately (without waiting for search).
    // Spawn searcher thread in background (for valid, it will search, but main exits immediately for no TTY).
    // For TTY, proceed to TUI (which will spawn searcher and show UI).
    let is_tty = std::io::stdout().is_terminal() && std::io::stdin().is_terminal();
    if !is_tty {
        // Spawn dummy searcher thread that would search (but we exit immediately, so it will be killed).
        // To match original's fast exit (0.005s), don't do heavy work, just return error.
        // Note: original spawns searcher even for no TTY valid (but exits fast, searcher killed). We do same (or nothing).
        return Err(anyhow::anyhow!(std::io::Error::from_raw_os_error(11)));
    }

    // TTY present and pattern valid: run TUI
    run_tui(pattern, paths, globs, types_select, types_negate, hidden_flag, follow_flag, ignore_case, smart_case, word_regexp, fixed_strings, multiline, context_viewer.clone(), sort_opt.cloned(), sortr_opt.cloned(), theme_is_light, editor_choice_to_data(&editor_choice))?;
    Ok(())
}

