// ===== Rendering helpers =====
fn build_display_lines(app: &App) -> Vec<DisplayLine> {
    #[derive(Debug, Clone)]
    enum DLKind { Header(usize), Match(usize, usize) } // file_idx, match_idx
    // We'll return Vec<DisplayLine> with enum
    Vec::new()
}

#[derive(Debug, Clone)]
enum DisplayLine {
    Header { file_idx: usize },
    Match { file_idx: usize, match_idx: usize, global_visible_idx: usize },
}

fn get_display_lines(app: &App) -> Vec<DisplayLine> {
    let mut lines = Vec::new();
    let vis_flat = app.visible_matches_flat();
    // Map (fi,mi) -> global idx
    let mut map: HashMap<(usize, usize), usize> = HashMap::new();
    for (gidx, (fi, mi)) in vis_flat.iter().enumerate() {
        map.insert((*fi, *mi), gidx);
    }
    for (fi, f) in app.files.iter().enumerate() {
        let vis_in_file: Vec<(usize, &MatchEntry)> = f.matches.iter().enumerate().filter(|(_, m)| !m.filtered).map(|(i, m)| (i, m)).collect();
        if vis_in_file.is_empty() {
            continue; // skip files with no visible matches (header disappears)
        }
        lines.push(DisplayLine::Header { file_idx: fi });
        for (mi, _) in vis_in_file {
            let gidx = *map.get(&(fi, mi)).unwrap();
            lines.push(DisplayLine::Match { file_idx: fi, match_idx: mi, global_visible_idx: gidx });
        }
    }
    lines
}

