// ===== Rendering =====
fn render_app(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    // area is full terminal (width x height). Status is last row, content is top height-1.
    let height = area.height as usize;
    let width = area.width as usize;
    if height == 0 { return; }
    let content_height = if height > 0 { height - 1 } else { 0 };
    let content_area = Rect { x: area.x, y: area.y, width: area.width, height: content_height as u16 };
    let status_area = Rect { x: area.x, y: area.y + content_height as u16, width: area.width, height: 1 };

    // Render main content based on viewer mode
