        .title(Span::styled("igrep 1.3.0", Style::default().fg(Color::Indexed(2))))
        .title_alignment(ratatui::layout::Alignment::Center);
    let inner = block.inner(popup_area);
    f.render_widget(block, popup_area);
    // Inner size should be 61x22 (63-2, 24-2). Good.
    // Top padding (inner row0): empty (61 spaces, no style)
    // Scrollable content (20 rows visible, total 30): header, separator, 26 keys, empty, footer
