    // For vertical scroll: offset app.keymap_scroll_v rows (0..10). Visible 20 rows from offset.
    // Build scrollable lines as Vec<String> (each 61 chars, plain text, no colors? Content text default, no colors. Borders green already via Block, middle │ default (not green). Good. So content lines have no style (default).
    let mut scrollable: Vec<String> = Vec::new();
    // Header: " Key(s)             │ Action                                 "
    // Left part 20 chars (" Key(s)             "): space + "Key(s)" (6) +13 spaces? Let's construct exactly as observed: " Key(s)             " (1+6+13=20)? Count: "Key(s)"=6, spaces after? "             " (13)? 1+6+13=20. Good.
    // Middle "│" (1)
    // Right part 40 chars (" Action                                 "): space + "Action" (6) +33 spaces? 1+6+33=40. Good. Total 20+1+40=61. Good.
    scrollable.push(format!(" {:<18} │ {:<38} ", "Key(s)", "Action"));
    // Separator: " ───────────────────┼─────────────────────────────────────── "
    // Left 19 dashes? Actually "───────────────────" (19?) Let's construct as observed: " ───────────────────┼─────────────────────────────────────── "
    // Left part before ┼: space + 19 dashes? Right part after ┼: 39 dashes + space? Total 1+19+1+39+1=61. Good. Need exact counts: left dashes 19? Right dashes 39? Let's verify from earlier: inner " ───────────────────┼─────────────────────────────────────── " – count dashes.
    // From earlier split, separator inner is single part (no │ split). Let's just use exact string from capture.
    scrollable.push(" ───────────────────┼─────────────────────────────────────── ".to_string());
    // Key rows from keymap_lines()
    for (k, a) in keymap_lines() {
        if k.is_empty() && a.is_empty() {
            // Empty split row: "                    │                                        "
            // Left 20 spaces? Actually "                    " (20 spaces) + "│" + "                                        " (40 spaces) =61? 20+1+40=61. Good.
            // But observed empty split row: "                    │                                        " – left 20 spaces, middle │, right 40 spaces. Good. Note: left/right have no leading/trailing extra? Actually left 20 spaces includes padding? For normal rows, left is " {keys:<18} " (space + keys padded to 18 + space)? For empty, keys="" -> "                    " (20 spaces: space + 18 spaces + space?) Good. Similarly right "                                        " (40 spaces: space + 38 spaces + space?) Good.
            scrollable.push(format!(" {:<18} │ {:<38} ", "", ""));
        } else {
            scrollable.push(format!(" {:<18} │ {:<38} ", k, a));
        }
    }
    // After keys (26 rows), empty full (61 spaces) and footer
    scrollable.push("                                                             ".to_string()); // 61 spaces? Count: 61 spaces. Original empty before footer is full spaces (no middle │). Good.
    // Footer: " Press any key to close…                                     "
    // "Press any key to close…" len? "Press"(5)+space(1)+"any"(3)+space(1)+"key"(3)+space(1)+"to"(2)+space(1)+"close…"(6: 5+1)=22. With leading space (1) +22 +38 spaces? 1+22+38=61. Good.
    scrollable.push(format!(" {:<59} ", "Press any key to close…"));
    // Total scrollable should be 1+1+26+1+1=30. Check.
    // Now render with scroll offsets
    // Inner area: inner.x, inner.y, inner.width (61), inner.height (22)
    // Top padding row (inner row0): empty (61 spaces)
    // Scrollable visible rows (inner rows1-20, 20 rows): from scrollable[offset .. offset+20)
    // Bottom padding row (inner row21): empty
    // Horizontal scroll: for each scrollable line string (61 chars), skip scroll_h chars and take 61? Since content width 61 fits, scroll_h max 0. Implement generic: chars().skip(scroll_h).take(inner.width)
    let inner_w = inner.width as usize;
    let inner_h = inner.height as usize; // should be 22
    // Top padding
    if inner_h >= 1 {
        let r = Rect { x: inner.x, y: inner.y, width: inner.width, height: 1 };
        let line = Line::from(Span::raw(" ".repeat(inner_w)));
        f.render_widget(Paragraph::new(line), r);
    }
    // Scrollable
    let v_off = app.keymap_scroll_v as usize;
    let h_off = app.keymap_scroll_h as usize;
    for i in 0..20 {
        if 1 + i >= inner_h - 1 { break; } // reserve bottom padding? Actually inner rows1-20 (20 rows) for scrollable, row21 bottom padding. Good. So i 0..19 -> inner y+1+i
        let y = inner.y + 1 + i as u16;
        if y >= inner.y + inner.height - 1 { break; } // stop before bottom padding? Actually bottom padding is last row (y+21). Scrollable rows are y+1 .. y+20 (20 rows). Good.
        let r = Rect { x: inner.x, y, width: inner.width, height: 1 };
        let content_idx = v_off + i;
        let text = if content_idx < scrollable.len() {
            let full = &scrollable[content_idx];
            // Apply horizontal scroll: skip h_off chars, take inner_w, pad with spaces if shorter
            let chars: Vec<char> = full.chars().collect();
            let skipped: String = chars.iter().skip(h_off).take(inner_w).collect();
            let skipped_len = skipped.chars().count();
            if skipped_len < inner_w {
                format!("{}{}", skipped, " ".repeat(inner_w - skipped_len))
            } else {
                skipped
            }
        } else {
            " ".repeat(inner_w)
        };
        let line = Line::from(Span::raw(text));
        f.render_widget(Paragraph::new(line), r);
    }
    // Bottom padding
    if inner_h >= 1 {
        let y = inner.y + inner.height - 1;
        let r = Rect { x: inner.x, y, width: inner.width, height: 1 };
        let line = Line::from(Span::raw(" ".repeat(inner_w)));
        f.render_widget(Paragraph::new(line), r);
    }
}

